IF EXISTS (
    SELECT player_name
    FROM @AppearanceInput
    UNION
    SELECT player_1_name FROM @EventInput WHERE player_1_name IS NOT NULL
    UNION
    SELECT player_2_name FROM @EventInput WHERE player_2_name IS NOT NULL
    EXCEPT
    SELECT person.name
    FROM dbo.person AS person
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id
)
BEGIN
    ;THROW 51121, 'Every event participant must resolve to a player profile.', 1;
END;

IF EXISTS (
    SELECT 1
    FROM @MatchMap AS match_map
    WHERE EXISTS (SELECT 1 FROM dbo.appearance WHERE match_id = match_map.match_id)
       OR EXISTS (SELECT 1 FROM dbo.match_event WHERE match_id = match_map.match_id)
)
BEGIN
    ;THROW 51122, 'A selected fixture already has appearance or event rows.', 1;
END;

BEGIN TRY
    BEGIN TRANSACTION;

    INSERT INTO dbo.appearance (match_id, player_id, is_starter)
    SELECT match_map.match_id, player.person_id, input.is_starter
    FROM @AppearanceInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.player_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id;

    INSERT INTO dbo.match_event (match_id, event_no, minute)
    SELECT match_map.match_id, input.event_no, input.minute
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id;

    INSERT INTO dbo.event_player (match_id, event_no, player_id, [role])
    SELECT match_map.match_id, input.event_no, player.person_id, input.player_1_role
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.player_1_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id
    WHERE input.player_1_name IS NOT NULL
    UNION ALL
    SELECT match_map.match_id, input.event_no, player.person_id, input.player_2_role
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.player_2_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id
    WHERE input.player_2_name IS NOT NULL;

    INSERT INTO dbo.goal (match_id, event_no, goal_type)
    SELECT match_map.match_id, input.event_no, input.goal_type
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    WHERE input.event_type = N'goal';

    INSERT INTO dbo.card (match_id, event_no, colour)
    SELECT match_map.match_id, input.event_no, input.card_colour
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    WHERE input.event_type = N'card';

    INSERT INTO dbo.substitution (match_id, event_no, is_injury)
    SELECT match_map.match_id, input.event_no, input.is_injury
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    WHERE input.event_type = N'substitution';

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
    BEGIN
        ROLLBACK TRANSACTION;
    END;

    THROW;
END CATCH;

